declare const tools: { mcp__t3_code__link_pull_requests(args: { environmentId?: string; threadId?: string; urls: Array<string>; }): Promise<CallToolResult<{ alreadyLinked: Array<{ host: string; numbers: Array<number>; repository: string; [key: string]: unknown; }>; invalidUrls?: Array<string> | null; linked: Array<{ host: string; numbers: Array<number>; repository: string; [key: string]: unknown; }>; linkedCount: number; next?: string | null; [key: string]: unknown; }>>; };
